252	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
253	    @Override
254	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
255	        Owner owner = this.clinicService.findOwnerById(ownerId);
256	        if (owner != null) {
257	            Pet pet = owner.getPet(petId);
258	            if (pet != null) {
259	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
260	            }
261	        }
262	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	    }
264	
265	    /**
266	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
267	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
268	     * the request body already rejects null and empty values, but permits whitespace-only strings
269	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
270	     * that gap so every required field must carry a non-blank value.
271	     *
272	     * @param ownerFieldsDto the submitted owner fields
273	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
274	     */
275	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
276	        List<String> missing = new ArrayList<>();
277	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
278	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
279	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
280	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
281	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
282	        if (!missing.isEmpty()) {
283	            throw new InvalidOwnerFieldsException(missing);
284	        }
285	    }
286	
287	    private void addIfBlank(List<String> missing, String fieldName, String value) {
288	        if (value == null || value.isBlank()) {
289	            missing.add(fieldName);
290	        }
291	    }
292	
293	    /**
294	     * Normalizes the submitted {@code address} on create to its canonical form (see
295	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
296	     * stored and returned, and the form every later address comparison (the required-field check,
297	     * household duplicate detection and the shared household id) is judged on. A null address is left
298	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
299	     * after normalization likewise reduces to the empty string and is rejected there.
300	     *
301	     * @param ownerFieldsDto the submitted owner fields
302	     */
303	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
304	        String address = ownerFieldsDto.getAddress();
305	        if (address == null) {
306	            return;
307	        }
308	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
309	    }
310	
311	    /**
312	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
313	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
314	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
315	     * {@code 400 Bad Request}.
316	     *
317	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
318	     *                       {@link #rejectBlankOwnerFields} having already run)
319	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
320	     */
321	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
322	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
323	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
324	        ownerFieldsDto.setTelephone(normalized);
325	    }
326	
327	    /**
328	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
329	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
330	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
331	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
332	     *
333	     * @param ownerFieldsDto the submitted owner fields
334	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
335	     */
336	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
337	        String email = ownerFieldsDto.getEmail();
338	        if (email == null || email.isBlank()) {
339	            return;
340	        }
341	        email = email.trim();
342	        if (!EMAIL_PATTERN.matcher(email).matches()) {
343	            throw new InvalidOwnerFieldsException(List.of("email"));
344	        }
345	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
346	    }
347	
348	    /**
349	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
350	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
351	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
352	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
353	     *
354	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
355	     *                            {@link #normalizeTelephone}
356	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
357	     */
358	    private void rejectDuplicateTelephone(String normalizedTelephone) {
359	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
360	        boolean inUse = this.clinicService.findAllOwners().stream()
361	            .map(Owner::getTelephone)
362	            .filter(Objects::nonNull)
363	            .map(TelephoneNormalizer::toComparisonKey)
364	            .anyMatch(comparisonKey::equals);
365	        if (inUse) {
366	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
367	        }
368	    }
369	
370	    /**
371	     * Rejects creating an owner who shares a household with any existing owner, unless the request
372	     * opts in with {@code sharesHousehold} set to {@code true}. Two owners share a household when they
373	     * have the same {@code lastName} and {@code address}, compared case-insensitively and with runs of
374	     * whitespace collapsed (see {@link HouseholdNormalizer}); the submitted fields and every existing
375	     * owner's stored fields are reduced to their {@linkplain HouseholdNormalizer#toComparisonKey
376	     * comparison key} before comparison. A match is reported as a {@code 409 Conflict}.
377	     *
378	     * @param ownerFieldsDto the submitted owner fields (its {@code lastName} and {@code address} are
379	     *                       non-blank here, {@link #rejectBlankOwnerFields} having already run)
380	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household and the
381	     *                                          request did not opt in with {@code sharesHousehold}
382	     */
383	    /**
384	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
385	     * both match the submitted values, compared case-insensitively. The count reflects only owners
386	     * already persisted at the time of the create, so the owner being created is never included.
387	     *
388	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
389	     *                  having already run)
390	     * @param lastName  the submitted last name (non-blank here)
391	     * @return the number of existing owners sharing the same first and last name
392	     */
393	    private int countNamesakes(String firstName, String lastName) {
394	        return (int) this.clinicService.findAllOwners().stream()
395	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
396	                && lastName.equalsIgnoreCase(owner.getLastName()))
397	            .count();
398	    }
399	
400	    /**
401	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
402	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
403	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
404	     *
405	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
406	     *             run)
407	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
408	     */
409	    private void rejectCityAtCapacity(String city) {
410	        long ownersInCity = this.clinicService.findAllOwners().stream()
411	            .map(Owner::getCity)
412	            .filter(Objects::nonNull)
413	            .filter(city::equalsIgnoreCase)
414	            .count();
415	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
416	            throw new OwnerCityAtCapacityException(city);
417	        }
418	    }
419	
420	    /**
421	     * Resolves the effective registration date for a create, rolled onto a business day. The
422	     * supplied date is used when present, otherwise the server's current date; either way the result
423	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
424	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
425	     * stored {@code registrationDate}, the membership number's year segment and the daily
426	     * create-limit's per-day count - is judged on this adjusted date.
427	     *
428	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
429	     *                                 default to the server's current date
430	     * @return the effective registration date, guaranteed to fall on a business day
431	     */
432	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
433	        LocalDate registrationDate =
434	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
435	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
436	    }
437	
438	    /**
439	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
440	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
441	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
442	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
443	     * Too Many Requests}.
444	     *
445	     * @param registrationDate the create's effective registration date, already rolled onto a business
446	     *                         day by {@link #effectiveRegistrationDate}
447	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
448	     *                                              owner registrations
449	     */
450	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate) {
451	        long registeredThatDay = this.clinicService.findAllOwners().stream()
452	            .map(Owner::getRegistrationDate)
453	            .filter(registrationDate::equals)
454	            .count();
455	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
456	            throw new OwnerDailyRegistrationLimitException(registrationDate);
457	        }
458	    }
459	
460	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
461	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
462	            return;
463	        }
464	        String comparisonKey = HouseholdNormalizer.toComparisonKey(
465	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
466	        boolean inUse = this.clinicService.findAllOwners().stream()
467	            .filter(owner -> owner.getLastName() != null && owner.getAddress() != null)
468	            .map(owner -> HouseholdNormalizer.toComparisonKey(owner.getLastName(), owner.getAddress()))
469	            .anyMatch(comparisonKey::equals);
470	        if (inUse) {
471	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
472	        }
473	    }
474	}
